import React, { useEffect, useState, useMemo } from 'react';
import { produtosAPI } from '../services/api';
import { formatCurrency } from '../utils/formatters';
import { Plus, Pencil, Trash, MagnifyingGlass } from '@phosphor-icons/react';
import { toast } from 'sonner';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '../components/ui/dialog';
import { Button } from '../components/ui/button';
import { useSortableTable, SortableHeader } from '../hooks/useSortableTable';

export default function ProdutosPage() {
  const [produtos, setProdutos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingProduto, setEditingProduto] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  
  // Filtrar produtos pelo termo de pesquisa
  const filteredProdutos = useMemo(() => {
    if (!searchTerm.trim()) return produtos;
    const term = searchTerm.toLowerCase();
    return produtos.filter(p => 
      p.nome?.toLowerCase().includes(term) ||
      p.categoria?.toLowerCase().includes(term) ||
      p.descricao?.toLowerCase().includes(term)
    );
  }, [produtos, searchTerm]);
  
  const { sortedData, requestSort, sortConfig } = useSortableTable(filteredProdutos, { key: 'nome', direction: 'asc' });
  const [formData, setFormData] = useState({
    nome: '',
    descricao: '',
    categoria: '',
    preco: '',
    custo: '',
    ncm: '18069000',
    cfop: '5102',
    cest: '',
    unidade_comercial: 'UN',
    ncm_code: '18063210',
    unidade: 'UN',
  });

  useEffect(() => {
    fetchProdutos();
  }, []);

  const fetchProdutos = async () => {
    try {
      const response = await produtosAPI.listar();
      setProdutos(response.data);
    } catch (error) {
      toast.error('Erro ao carregar produtos');
    } finally {
      setLoading(false);
    }
  };

  // Verifica se já existe produto com mesmo nome
  const verificarDuplicata = (dados) => {
    console.log('Verificando duplicatas. Produtos carregados:', produtos.length);
    console.log('Dados do novo produto:', dados);
    
    const duplicatas = produtos.filter(p => {
      if (editingProduto && p.id === editingProduto.id) return false;
      const nomeIgual = p.nome && dados.nome && 
        p.nome.toLowerCase().trim() === dados.nome.toLowerCase().trim();
      console.log(`Comparando "${p.nome}" com "${dados.nome}": ${nomeIgual}`);
      return nomeIgual;
    });
    
    console.log('Duplicatas encontradas:', duplicatas);
    return duplicatas;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const data = {
        ...formData,
        preco: parseFloat(formData.preco),
        custo: parseFloat(formData.custo || 0),
        ncm: formData.ncm || '18069000',
        cfop: formData.cfop || '5102',
        cest: formData.cest || null,
        unidade_comercial: formData.unidade_comercial || 'UN',
      };

      // Verificar duplicatas apenas em novos cadastros
      if (!editingProduto) {
        // Recarregar produtos para garantir lista atualizada
        let produtosAtuais = produtos;
        try {
          const response = await produtosAPI.listar();
          produtosAtuais = response.data;
        } catch (e) {
          console.error('Erro ao buscar produtos para verificação:', e);
        }
        
        const duplicatas = produtosAtuais.filter(p => 
          p.nome && data.nome && 
          p.nome.toLowerCase().trim() === data.nome.toLowerCase().trim()
        );
        
        if (duplicatas.length > 0) {
          const confirmar = window.confirm(
            `Já existe um produto com nome igual ou similar:\n\n` +
            duplicatas.map(d => `• ${d.nome} (${d.categoria || 'Sem categoria'})`).join('\n') +
            `\n\nDeseja cadastrar mesmo assim?`
          );
          
          if (!confirmar) return;
        }
      }

      if (editingProduto) {
        await produtosAPI.atualizar(editingProduto.id, data);
        toast.success('Produto atualizado com sucesso');
      } else {
        await produtosAPI.criar(data);
        toast.success('Produto criado com sucesso');
      }
      setDialogOpen(false);
      resetForm();
      fetchProdutos();
    } catch (error) {
      toast.error('Erro ao salvar produto');
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Deseja realmente excluir este produto?')) {
      try {
        await produtosAPI.deletar(id);
        toast.success('Produto excluído com sucesso');
        fetchProdutos();
      } catch (error) {
        toast.error('Erro ao excluir produto');
      }
    }
  };

  const handleEdit = (produto) => {
    setEditingProduto(produto);
    setFormData({
      nome: produto.nome,
      descricao: produto.descricao || '',
      categoria: produto.categoria,
      preco: produto.preco.toString(),
      custo: (produto.custo || 0).toString(),
      ncm: produto.ncm || '18069000',
      cfop: produto.cfop || '5102',
      cest: produto.cest || '',
      unidade_comercial: produto.unidade_comercial || 'UN',
      ncm_code: produto.ncm_code || '18063210',
      unidade: produto.unidade || 'UN',
    });
    setDialogOpen(true);
  };

  const resetForm = () => {
    setFormData({
      nome: '',
      descricao: '',
      categoria: '',
      preco: '',
      custo: '',
      ncm: '18069000',
      cfop: '5102',
      cest: '',
      unidade_comercial: 'UN',
      ncm_code: '18063210',
      unidade: 'UN',
    });
    setEditingProduto(null);
  };

  if (loading) {
    return <div className="flex items-center justify-center py-12"><p className="text-[#6B4423] font-sans">Carregando...</p></div>;
  }

  return (
    <div data-testid="produtos-page">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-4xl sm:text-5xl font-serif font-bold tracking-tight text-[#3E2723] mb-2">Produtos</h1>
          <p className="text-base font-sans text-[#705A4D]">Gerencie o catálogo de chocolates</p>
        </div>
        <Dialog open={dialogOpen} onOpenChange={(open) => { setDialogOpen(open); if (!open) resetForm(); }}>
          <DialogTrigger asChild>
            <Button data-testid="btn-add-produto" className="bg-[#6B4423] text-[#F5E6D3] hover:bg-[#8B5A3C]">
              <Plus size={20} weight="bold" className="mr-2" />
              Novo Produto
            </Button>
          </DialogTrigger>
          <DialogContent className="bg-[#FFFDF8] max-w-2xl">
            <DialogHeader>
              <DialogTitle className="text-2xl font-serif text-[#3E2723]">
                {editingProduto ? 'Editar Produto' : 'Novo Produto'}
              </DialogTitle>
            </DialogHeader>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-[#6B4423] mb-1">Nome *</label>
                  <input
                    type="text"
                    required
                    value={formData.nome}
                    onChange={(e) => setFormData({ ...formData, nome: e.target.value })}
                    className="w-full px-4 py-2.5 bg-[#FFFDF8] border border-[#8B5A3C]/30 rounded-lg focus:border-[#6B4423] focus:ring-1 focus:ring-[#6B4423] outline-none text-[#3E2723] font-sans"
                  />
                </div>
                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-[#6B4423] mb-1">Descrição</label>
                  <textarea
                    value={formData.descricao}
                    onChange={(e) => setFormData({ ...formData, descricao: e.target.value })}
                    rows="2"
                    className="w-full px-4 py-2.5 bg-[#FFFDF8] border border-[#8B5A3C]/30 rounded-lg focus:border-[#6B4423] focus:ring-1 focus:ring-[#6B4423] outline-none text-[#3E2723] font-sans"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-[#6B4423] mb-1">Categoria *</label>
                  <input
                    type="text"
                    required
                    list="categorias-sugestoes"
                    value={formData.categoria}
                    onChange={(e) => setFormData({ ...formData, categoria: e.target.value })}
                    className="w-full px-4 py-2.5 bg-[#FFFDF8] border border-[#8B5A3C]/30 rounded-lg focus:border-[#6B4423] focus:ring-1 focus:ring-[#6B4423] outline-none text-[#3E2723] font-sans"
                    placeholder="Digite ou selecione uma categoria"
                  />
                  <datalist id="categorias-sugestoes">
                    {/* Categorias dos produtos existentes */}
                    {[...new Set(produtos.map(p => p.categoria).filter(Boolean))].sort().map((cat) => (
                      <option key={cat} value={cat} />
                    ))}
                    {/* Categorias padrão caso não existam produtos */}
                    {produtos.length === 0 && (
                      <>
                        <option value="Trufas" />
                        <option value="Bombons" />
                        <option value="Barras" />
                        <option value="Ovos de Páscoa" />
                        <option value="Tabletes" />
                        <option value="Palitos" />
                        <option value="Coberturas" />
                        <option value="Recheios" />
                        <option value="Outros" />
                      </>
                    )}
                  </datalist>
                  <p className="text-xs text-[#705A4D] mt-1">
                    Você pode escolher uma sugestão ou digitar uma nova categoria
                  </p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-[#6B4423] mb-1">Preço de Venda *</label>
                  <input
                    type="number"
                    step="0.01"
                    required
                    value={formData.preco}
                    onChange={(e) => setFormData({ ...formData, preco: e.target.value })}
                    className="w-full px-4 py-2.5 bg-[#FFFDF8] border border-[#8B5A3C]/30 rounded-lg focus:border-[#6B4423] focus:ring-1 focus:ring-[#6B4423] outline-none text-[#3E2723] font-sans"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-[#6B4423] mb-1">Custo de Produção</label>
                  <input
                    type="number"
                    step="0.01"
                    value={formData.custo}
                    onChange={(e) => setFormData({ ...formData, custo: e.target.value })}
                    className="w-full px-4 py-2.5 bg-[#FFFDF8] border border-[#8B5A3C]/30 rounded-lg focus:border-[#6B4423] focus:ring-1 focus:ring-[#6B4423] outline-none text-[#3E2723] font-sans"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-[#6B4423] mb-1">Unidade</label>
                  <input
                    type="text"
                    value={formData.unidade}
                    onChange={(e) => setFormData({ ...formData, unidade: e.target.value })}
                    className="w-full px-4 py-2.5 bg-[#FFFDF8] border border-[#8B5A3C]/30 rounded-lg focus:border-[#6B4423] focus:ring-1 focus:ring-[#6B4423] outline-none text-[#3E2723] font-sans"
                  />
                </div>
              </div>

              {/* Seção Fiscal */}
              <div className="border-t border-[#8B5A3C]/15 pt-4">
                <p className="text-sm font-semibold text-[#6B4423] mb-3">📋 Dados Fiscais (NFC-e)</p>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-[#6B4423] mb-1">
                      NCM
                      <span className="ml-1 text-xs text-[#8B5A3C] font-normal">(8 dígitos)</span>
                    </label>
                    <input
                      type="text"
                      maxLength={8}
                      placeholder="18069000"
                      value={formData.ncm}
                      onChange={(e) => setFormData({ ...formData, ncm: e.target.value.replace(/\D/g,'') })}
                      className="w-full px-4 py-2.5 bg-[#FFFDF8] border border-[#8B5A3C]/30 rounded-lg focus:border-[#6B4423] focus:ring-1 focus:ring-[#6B4423] outline-none text-[#3E2723] font-sans font-mono"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[#6B4423] mb-1">
                      CFOP
                      <span className="ml-1 text-xs text-[#8B5A3C] font-normal">(4 dígitos)</span>
                    </label>
                    <select
                      value={formData.cfop}
                      onChange={(e) => setFormData({ ...formData, cfop: e.target.value })}
                      className="w-full px-4 py-2.5 bg-[#FFFDF8] border border-[#8B5A3C]/30 rounded-lg focus:border-[#6B4423] focus:ring-1 focus:ring-[#6B4423] outline-none text-[#3E2723] font-sans"
                    >
                      <option value="5102">5102 — Venda de mercadoria adquirida</option>
                      <option value="5101">5101 — Venda de produção do estabelecimento</option>
                      <option value="5405">5405 — Venda c/ substituição tributária</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[#6B4423] mb-1">
                      Unidade Comercial
                    </label>
                    <select
                      value={formData.unidade_comercial}
                      onChange={(e) => setFormData({ ...formData, unidade_comercial: e.target.value })}
                      className="w-full px-4 py-2.5 bg-[#FFFDF8] border border-[#8B5A3C]/30 rounded-lg focus:border-[#6B4423] focus:ring-1 focus:ring-[#6B4423] outline-none text-[#3E2723] font-sans"
                    >
                      <option value="UN">UN — Unidade</option>
                      <option value="CX">CX — Caixa</option>
                      <option value="KG">KG — Quilograma</option>
                      <option value="GR">GR — Grama</option>
                      <option value="PC">PC — Pacote</option>
                      <option value="BL">BL — Bloco</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-[#6B4423] mb-1">
                      CEST
                      <span className="ml-1 text-xs text-[#8B5A3C] font-normal">(opcional)</span>
                    </label>
                    <input
                      type="text"
                      maxLength={7}
                      placeholder="Ex: 1700200"
                      value={formData.cest}
                      onChange={(e) => setFormData({ ...formData, cest: e.target.value.replace(/\D/g,'') })}
                      className="w-full px-4 py-2.5 bg-[#FFFDF8] border border-[#8B5A3C]/30 rounded-lg focus:border-[#6B4423] focus:ring-1 focus:ring-[#6B4423] outline-none text-[#3E2723] font-sans font-mono"
                    />
                  </div>
                </div>
              </div>

              <div className="flex gap-3 justify-end pt-4">
                <Button type="button" onClick={() => { setDialogOpen(false); resetForm(); }} variant="outline">
                  Cancelar
                </Button>
                <Button type="submit" className="bg-[#6B4423] text-[#F5E6D3] hover:bg-[#8B5A3C]">
                  {editingProduto ? 'Atualizar' : 'Criar'}
                </Button>
              </div>
            </form>
          </DialogContent>
        </Dialog>
      </div>

      {/* Campo de Pesquisa */}
      <div className="mb-4">
        <div className="relative max-w-md">
          <MagnifyingGlass size={20} weight="bold" className="absolute left-3 top-1/2 transform -translate-y-1/2 text-[#8B5A3C]" />
          <input
            type="text"
            placeholder="Pesquisar por nome, categoria, descrição..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 bg-[#FFFDF8] border border-[#8B5A3C]/30 rounded-lg focus:border-[#6B4423] focus:ring-1 focus:ring-[#6B4423] outline-none text-[#3E2723] font-sans placeholder:text-[#8B5A3C]/60"
          />
          {searchTerm && (
            <button onClick={() => setSearchTerm('')} className="absolute right-3 top-1/2 transform -translate-y-1/2 text-[#8B5A3C] hover:text-[#6B4423]">✕</button>
          )}
        </div>
        {searchTerm && (
          <p className="text-xs text-[#705A4D] mt-1">Encontrados: {filteredProdutos.length} de {produtos.length} produtos</p>
        )}
      </div>

      <div className="bg-[#FFFDF8] border border-[#8B5A3C]/15 rounded-xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-[#E8D5C4]">
              <tr>
                <SortableHeader label="Nome" sortKey="nome" sortConfig={sortConfig} onSort={requestSort} className="text-left" />
                <SortableHeader label="Categoria" sortKey="categoria" sortConfig={sortConfig} onSort={requestSort} className="text-left" />
                <SortableHeader label="Descrição" sortKey="descricao" sortConfig={sortConfig} onSort={requestSort} className="text-left" />
                <SortableHeader label="Preço" sortKey="preco" sortConfig={sortConfig} onSort={requestSort} className="text-right" />
                <SortableHeader label="Custo" sortKey="custo" sortConfig={sortConfig} onSort={requestSort} className="text-right" />
                <th className="text-right px-6 py-4 text-sm font-sans font-semibold text-[#3E2723]">Ações</th>
              </tr>
            </thead>
            <tbody>
              {sortedData.length === 0 ? (
                <tr>
                  <td colSpan="6" className="text-center py-12 text-[#705A4D] font-sans">
                    Nenhum produto cadastrado
                  </td>
                </tr>
              ) : (
                sortedData.map((produto) => (
                  <tr key={produto.id} className="border-t border-[#8B5A3C]/10 hover:bg-[#F5E6D3]/50">
                    <td className="px-6 py-4 text-sm text-[#4A3B32] font-sans font-medium">{produto.nome}</td>
                    <td className="px-6 py-4 text-sm text-[#4A3B32] font-sans">{produto.categoria}</td>
                    <td className="px-6 py-4 text-sm text-[#4A3B32] font-sans">{produto.descricao || '-'}</td>
                    <td className="px-6 py-4 text-sm text-[#4A3B32] font-sans text-right">{formatCurrency(produto.preco)}</td>
                    <td className="px-6 py-4 text-sm text-[#4A3B32] font-sans text-right">{formatCurrency(produto.custo || 0)}</td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex gap-2 justify-end">
                        <button
                          onClick={() => handleEdit(produto)}
                          className="p-2 text-[#6B4423] hover:bg-[#E8D5C4] rounded-lg transition-colors"
                        >
                          <Pencil size={18} />
                        </button>
                        <button
                          onClick={() => handleDelete(produto.id)}
                          className="p-2 text-[#C53030] hover:bg-[#FED7D7] rounded-lg transition-colors"
                        >
                          <Trash size={18} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}